1	param(
2	    [int]$ApiPort = 8016,
3	    [int]$FrontendPort = 5173,
4	    [string]$DatabasePath = ".local_paper_console.db"
5	)
6	
7	# One-click launcher - same pattern as 辅助面试/scripts/launch-experience.ps1
8	$ErrorActionPreference = "Stop"
9	
10	$Root = (Resolve-Path (Join-Path $PSScriptRoot "..")).Path
11	Set-Location -LiteralPath $Root
12	
13	$ApiHealthUrl = "http://127.0.0.1:$ApiPort/health"
14	$FrontendUrl = "http://127.0.0.1:$FrontendPort/trading"
15	$LogsDir = Join-Path $Root "logs"
16	$ApiLog = Join-Path $LogsDir "api.log"
17	$FrontendLog = Join-Path $LogsDir "frontend.log"
18	$StartupLog = Join-Path $LogsDir "startup-last.log"
19	$ApiPidFile = Join-Path $LogsDir "api.pid"
20	$SchedulerPidFile = Join-Path $LogsDir "scheduler.pid"
21	$SchedulerStateFile = Join-Path $LogsDir "scheduler-state.json"
22	$SchedulerLog = Join-Path $LogsDir "scheduler.log"
23	$SchedulerErrorLog = Join-Path $LogsDir "scheduler-error.log"
24	$FrontendPidFile = Join-Path $LogsDir "frontend.pid"
25	$DbPath = Join-Path $Root $DatabasePath
26	$SqliteUrl = "sqlite:///$($DbPath.Replace('\', '/'))"
27	
28	$env:NO_PROXY = "127.0.0.1,localhost"
29	$env:HTTP_PROXY = ""
30	$env:HTTPS_PROXY = ""
31	
32	function Test-EndpointReady([string]$Url) {
33	    try {
34	        $resp = Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 3 -Proxy $null
35	        return $resp.StatusCode -ge 200 -and $resp.StatusCode -lt 500
36	    }
37	    catch {
38	        return $false
39	    }
40	}
41	
42	function Write-Step([string]$Message) {
43	    $line = "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') [paper-console] $Message"
44	    Write-Host $line
45	    Add-Content -LiteralPath $StartupLog -Value $line -Encoding utf8
46	}
47	
48	function Reset-LogFile([string]$Path) {
49	    if (-not (Test-Path -LiteralPath $Path)) {
50	        New-Item -ItemType File -Path $Path | Out-Null
51	        return
52	    }
53	    try {
54	        [System.IO.File]::WriteAllText($Path, "")
55	    }
56	    catch {
57	        Write-Host "Log file is in use, continuing without reset: $Path"
58	    }
59	}
60	
61	function Stop-RecordedProcess([string]$PidFile, [int]$Port) {
62	    if (Test-Path -LiteralPath $PidFile) {
63	        $recordedPid = (Get-Content -LiteralPath $PidFile -Raw).Trim()
64	        if ($recordedPid -match '^\d+$') {
65	            $processInfo = Get-Process -Id ([int]$recordedPid) -ErrorAction SilentlyContinue
66	            if ($processInfo) {
67	                Write-Step "stopping prior launcher process on port $Port (pid $recordedPid)"
68	                Stop-ProcessTree -RootPid ([int]$recordedPid)
69	                Start-Sleep -Milliseconds 500
70	            }
71	        }
72	        Remove-Item -LiteralPath $PidFile -Force -ErrorAction SilentlyContinue
73	    }
74	
75	    $listeners = Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $Port -State Listen -ErrorAction SilentlyContinue
76	    if ($listeners) {
77	        $owner = $listeners | Select-Object -First 1 -ExpandProperty OwningProcess
78	        $ownerInfo = Get-CimInstance Win32_Process -Filter "ProcessId = $owner" -ErrorAction SilentlyContinue
79	        $commandLine = [string]$ownerInfo.CommandLine
80	        if ($commandLine -match "apps\.api\.(main|local_server)" -or $commandLine -match "vite\.js") {
81	            Write-Step "removing legacy project listener on port $Port (pid $owner)"
82	            Stop-ProcessTree -RootPid ([int]$owner)
83	            Start-Sleep -Milliseconds 500
84	        }
85	        else {
86	            throw "Port $Port is already in use by pid $owner. The launcher will not stop an unrecorded process."
87	        }
88	    }
89	}
90	
91	function Stop-ProcessTree([int]$RootPid) {
92	    $children = Get-CimInstance Win32_Process -Filter "ParentProcessId = $RootPid" -ErrorAction SilentlyContinue
93	    foreach ($child in $children) {
94	        Stop-ProcessTree -RootPid $child.ProcessId
95	    }
96	    Stop-Process -Id $RootPid -Force -ErrorAction SilentlyContinue
97	}
98	
99	function Save-ListenerPid([int]$Port, [string]$PidFile) {
100	    $listener = Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $Port -State Listen -ErrorAction SilentlyContinue |
101	        Select-Object -First 1
102	    if (-not $listener) {
103	        throw "No listener was found on port $Port after startup."
104	    }
105	    Set-Content -LiteralPath $PidFile -Value $listener.OwningProcess -Encoding ascii
106	}
107	
108	function Test-ProjectListener([int]$Port) {
109	    $listener = Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $Port -State Listen -ErrorAction SilentlyContinue |
110	        Select-Object -First 1
111	    if (-not $listener) { return $false }
112	    $ownerInfo = Get-CimInstance Win32_Process -Filter "ProcessId = $($listener.OwningProcess)" -ErrorAction SilentlyContinue
113	    $commandLine = [string]$ownerInfo.CommandLine
114	    if ($commandLine -match "apps\.api\.(main|local_server)") {
115	        return $commandLine -match "--local-console"
116	    }
117	    return $commandLine -match "量化项目.*vite\.js"
118	}
119	
120	function Stop-RecordedScheduler {
121	    if (-not (Test-Path -LiteralPath $SchedulerPidFile)) { return }
122	    $recordedPid = (Get-Content -LiteralPath $SchedulerPidFile -Raw).Trim()
123	    if ($recordedPid -match '^\d+$') {
124	        $ownerInfo = Get-CimInstance Win32_Process -Filter "ProcessId = $recordedPid" -ErrorAction SilentlyContinue
125	        if ([string]$ownerInfo.CommandLine -match "run-local-paper-scheduler\.py") {
126	            Write-Step "stopping prior local scheduler (pid $recordedPid)"
127	            Stop-ProcessTree -RootPid ([int]$recordedPid)
128	        }
129	    }
130	    Remove-Item -LiteralPath $SchedulerPidFile -Force -ErrorAction SilentlyContinue
131	}
132	
133	function Test-SchedulerHealthy {
134	    if (-not (Test-Path -LiteralPath $SchedulerPidFile) -or -not (Test-Path -LiteralPath $SchedulerStateFile)) {
135	        return $false
136	    }
137	    $schedulerPid = (Get-Content -LiteralPath $SchedulerPidFile -Raw).Trim()
138	    if ($schedulerPid -notmatch '^\d+$' -or -not (Get-Process -Id ([int]$schedulerPid) -ErrorAction SilentlyContinue)) {
139	        return $false
140	    }
141	    try {
142	        $state = Get-Content -LiteralPath $SchedulerStateFile -Raw | ConvertFrom-Json
143	        if (-not $state.running -or -not $state.heartbeat_at) { return $false }
144	        $heartbeat = [datetimeoffset]::Parse($state.heartbeat_at)
145	        return ((([datetimeoffset]::UtcNow - $heartbeat).TotalSeconds) -le 120)
146	    }
147	    catch {
148	        return $false
149	    }
150	}
