152	function Open-Frontend([string]$Url) {
153	    foreach ($browser in @("msedge.exe", "chrome.exe")) {
154	        $command = Get-Command $browser -ErrorAction SilentlyContinue
155	        if ($command) {
156	            Start-Process -FilePath $command.Source -ArgumentList $Url | Out-Null
157	            return $true
158	        }
159	    }
160	    Start-Process $Url | Out-Null
161	    return $true
162	}
163	
164	function Ensure-Runtime {
165	    if (-not (Get-Command npm.cmd -ErrorAction SilentlyContinue)) {
166	        throw "Node.js/npm not found."
167	    }
168	    if (-not (Test-Path -LiteralPath $LogsDir)) {
169	        New-Item -ItemType Directory -Path $LogsDir | Out-Null
170	    }
171	    Reset-LogFile $StartupLog
172	    Reset-LogFile $ApiLog
173	    Reset-LogFile $FrontendLog
174	
175	    if (-not $env:AGENT_PYTHON -or -not (Test-Path -LiteralPath $env:AGENT_PYTHON)) {
176	        $globalPython = Join-Path $HOME ".ai-workspace\venv\Scripts\python.exe"
177	        if (Test-Path -LiteralPath $globalPython) {
178	            $env:AGENT_PYTHON = $globalPython
179	        }
180	        else {
181	            throw "AGENT_PYTHON is unavailable. Run verify-global-agent-stack.ps1."
182	        }
183	    }
184	
185	    Write-Step "checking frontend dependency versions"
186	    npm ls --workspace frontend/admin --depth=0 *> $null
187	    if ($LASTEXITCODE -ne 0) {
188	        Write-Step "frontend dependencies are missing or stale; running npm install"
189	        npm install
190	        if ($LASTEXITCODE -ne 0) {
191	            throw "npm install failed. See npm output above."
192	        }
193	    }
194	    . (Join-Path $PSScriptRoot "load-dotenv.ps1")
195	    $envPath = Join-Path $Root ".env"
196	    if (Test-Path -LiteralPath $envPath) {
197	        Import-DotEnv $envPath | Out-Null
198	    }
199	    if (-not $env:BINANCE_HTTPS_PROXY -and $env:HTTPS_PROXY) {
200	        $env:BINANCE_HTTPS_PROXY = $env:HTTPS_PROXY
201	    }
202	    if (-not $env:BINANCE_HTTPS_PROXY) {
203	        $env:PAPER_CONSOLE_DISABLE_LIVE_WS = "true"
204	        $env:PAPER_CONSOLE_SKIP_BACKGROUND_BOOTSTRAP = "true"
205	        Write-Step "no Binance proxy configured; disabling live WebSocket collectors for startup stability"
206	    }
207	    else {
208	        $env:PAPER_CONSOLE_DISABLE_LIVE_WS = "false"
209	        $env:PAPER_CONSOLE_SKIP_BACKGROUND_BOOTSTRAP = "false"
210	    }
211	    $env:POSTGRES_URL = $SqliteUrl
212	    $env:VITE_API_BASE_URL = "http://127.0.0.1:$ApiPort"
213	    $env:CORS_ALLOWED_ORIGINS = "http://127.0.0.1:$FrontendPort,http://localhost:$FrontendPort"
214	    $env:APP_ENV = "development"
215	    $env:BINANCE_USE_TESTNET = "true"
216	    $env:LIVE_TRADING_ENABLED = "false"
217	    $env:RUNTIME_SCHEDULER_MODE = "inprocess"
218	    $env:RUNTIME_SCHEDULER_AUTOSTART = "true"
219	    $env:BINANCE_LIVE_UNIVERSE_ENABLED = "true"
220	    $env:BINANCE_LIVE_MARKET_ENABLED = "true"
221	    $env:BINANCE_LIVE_WS_ENABLED = if ($env:PAPER_CONSOLE_DISABLE_LIVE_WS -eq "true") { "false" } else { "true" }
222	    # The isolated scheduler owns background work; foreground market endpoints
223	    # must still be allowed to read Binance REST data for the trading console.
224	    $env:PAPER_CONSOLE_API_ONLY = "true"
225	    Remove-Item Env:VITE_LOCAL_CONSOLE_API_ONLY -ErrorAction SilentlyContinue
226	    Write-Step "starting isolated Paper scheduler; Testnet mirror remains cost-gated"
227	}
228	
229	function Initialize-LocalDatabase {
230	    Write-Step "preparing local database"
231	    & $env:AGENT_PYTHON scripts/prepare_database.py --database-url $SqliteUrl | Out-Null
232	    if ($LASTEXITCODE -ne 0) { throw "Local database preparation failed; API will not start against an incomplete schema." }
233	}
234	
235	$apiReady = Test-EndpointReady $ApiHealthUrl
236	$frontendReady = Test-EndpointReady "http://127.0.0.1:$FrontendPort/"
237	
238	if ($apiReady -and $frontendReady -and (Test-ProjectListener $ApiPort) -and (Test-ProjectListener $FrontendPort)) {
239	    if (-not (Test-SchedulerHealthy)) {
240	        Ensure-Runtime
241	        Stop-RecordedScheduler
242	        Reset-LogFile $SchedulerLog
243	        Reset-LogFile $SchedulerErrorLog
244	        $schedulerScript = Join-Path $PSScriptRoot "run-local-paper-scheduler.py"
245	        $schedulerProcess = Start-Process -FilePath $env:AGENT_PYTHON `
246	            -ArgumentList @($schedulerScript, "--database-url", $SqliteUrl) `
247	            -WorkingDirectory $Root `
248	            -WindowStyle Hidden `
249	            -RedirectStandardOutput $SchedulerLog `
250	            -RedirectStandardError $SchedulerErrorLog `
251	            -PassThru
252	        Set-Content -LiteralPath $SchedulerPidFile -Value $schedulerProcess.Id -Encoding ascii
253	        Start-Sleep -Seconds 2
254	        if (-not (Test-SchedulerHealthy)) {
255	            throw "Paper scheduler failed its startup health check. See $SchedulerLog"
256	        }
257	    }
258	    if (-not (Test-Path -LiteralPath $LogsDir)) { New-Item -ItemType Directory -Path $LogsDir | Out-Null }
259	    if (-not (Test-Path -LiteralPath $StartupLog)) { New-Item -ItemType File -Path $StartupLog | Out-Null }
260	    Write-Step "paper console already running"
261	    Save-ListenerPid $ApiPort $ApiPidFile
262	    Save-ListenerPid $FrontendPort $FrontendPidFile
263	    Write-Step "frontend: $FrontendUrl"
264	    Write-Step "opening browser"
265	    [void](Open-Frontend $FrontendUrl)
266	    exit 0
267	}
268	
269	Ensure-Runtime
270	Initialize-LocalDatabase
271	
272	if (-not $apiReady) { Stop-RecordedProcess $ApiPidFile $ApiPort }
273	if (-not $frontendReady) { Stop-RecordedProcess $FrontendPidFile $FrontendPort }
274	
275	if (-not $apiReady) {
276	    Write-Step "starting API http://127.0.0.1:$ApiPort"
277	    # Start Uvicorn directly. PowerShell wrapper processes can retain inherited
278	    # handles and make the Windows ASGI server accept connections without serving them.
279	    $apiProcess = Start-Process -FilePath $env:AGENT_PYTHON `
280	        -ArgumentList @("-m", "apps.api.local_server", "--host", "127.0.0.1", "--port", $ApiPort, "--log-level", "warning", "--local-console") `
281	        -WorkingDirectory $Root `
282	        -WindowStyle Hidden `
283	        -PassThru
284	    Set-Content -LiteralPath $ApiPidFile -Value $apiProcess.Id -Encoding ascii
285	}
286	
287	Stop-RecordedScheduler
288	Reset-LogFile $SchedulerLog
289	Reset-LogFile $SchedulerErrorLog
290	$schedulerScript = Join-Path $PSScriptRoot "run-local-paper-scheduler.py"
291	$schedulerProcess = Start-Process -FilePath $env:AGENT_PYTHON `
292	    -ArgumentList @($schedulerScript, "--database-url", $SqliteUrl) `
293	    -WorkingDirectory $Root `
294	    -WindowStyle Hidden `
295	    -RedirectStandardOutput $SchedulerLog `
296	    -RedirectStandardError $SchedulerErrorLog `
297	    -PassThru
298	Set-Content -LiteralPath $SchedulerPidFile -Value $schedulerProcess.Id -Encoding ascii
299	
300	if (-not $frontendReady) {
301	    Write-Step "starting frontend http://127.0.0.1:$FrontendPort"
302	    $frontendCmd = "npm --workspace frontend/admin run dev -- --host 127.0.0.1 --port $FrontendPort >> `"$FrontendLog`" 2>&1"
303	    $frontendProcess = Start-Process -FilePath "cmd.exe" `
304	        -ArgumentList @("/d", "/s", "/c", $frontendCmd) `
305	        -WorkingDirectory $Root `
306	        -WindowStyle Hidden `
307	        -PassThru
308	    Set-Content -LiteralPath $FrontendPidFile -Value $frontendProcess.Id -Encoding ascii
309	}
310	
311	Write-Step "waiting for services (up to 90s)"
312	$deadline = (Get-Date).AddSeconds(90)
313	while ((Get-Date) -lt $deadline) {
314	    if (-not $apiReady) { $apiReady = Test-EndpointReady $ApiHealthUrl }
315	    if (-not $frontendReady) { $frontendReady = Test-EndpointReady "http://127.0.0.1:$FrontendPort/" }
316	    if ($apiReady -and $frontendReady) { break }
317	    Start-Sleep -Seconds 1
318	}
319	
320	if ($apiReady -and $frontendReady) {
321	    Save-ListenerPid $ApiPort $ApiPidFile
322	    Save-ListenerPid $FrontendPort $FrontendPidFile
323	    Write-Step "services ready"
324	    Write-Step "frontend: $FrontendUrl"
325	    Write-Step "API: http://127.0.0.1:$ApiPort"
326	    Write-Step "opening browser"
327	    [void](Open-Frontend $FrontendUrl)
328	    exit 0
329	}
330	
331	Write-Step "startup failed"
332	Write-Step "check logs: $ApiLog ; $FrontendLog"
333	Remove-Item -LiteralPath $ApiPidFile,$FrontendPidFile -Force -ErrorAction SilentlyContinue
334	if (Test-Path -LiteralPath $ApiLog) {
335	    Write-Host "--- api.log (tail) ---"
336	    Get-Content -LiteralPath $ApiLog -Tail 15 -ErrorAction SilentlyContinue
337	}
338	if (Test-Path -LiteralPath $FrontendLog) {
339	    Write-Host "--- frontend.log (tail) ---"
340	    Get-Content -LiteralPath $FrontendLog -Tail 15 -ErrorAction SilentlyContinue
341	}
342	Write-Step "browser was not opened because startup did not finish"
343	exit 1
